# Valores viejos que hay en la base -> valor correcto de la lista de unidades
UNIDADES = {
    "kg": "kg", "g": "g", "l": "l", "ml": "ml", "u": "u",
    "un": "u", "unidad": "u", "unidades": "u", "litro": "l", "litros": "l",
}


def normalizar_unidades(apps, schema_editor):
    """Deja todas las unidades en minúsculas y con los valores de la lista."""
    Ingrediente = apps.get_model("inventario", "Ingrediente")
    for ingrediente in Ingrediente.objects.all():
        correcta = UNIDADES.get(ingrediente.unidad_medida.strip().lower())
        if correcta and correcta != ingrediente.unidad_medida:
            Ingrediente.objects.filter(pk=ingrediente.pk).update(unidad_medida=correcta)


